// The account id and username, or why the token was refused. A token from the dashboard lasts 60 days.
// Instagram's own words from an HTTP error ('400 - "{\"error\":{\"message\": ...}}"'), else the raw message.
const igError = e => { const m = String(e?.message || e || ''); let t = m.slice(m.indexOf(' - ') + 3);
  for (let i = 0; i < 2; i++) { try { t = JSON.parse(t); } catch (x) { break; } if (typeof t !== 'string') break; }
  return (t && t.error && (t.error.error_user_msg || t.error.message)) || m; };
const me = $input.first().json || {};
const ok = !!me.user_id && !me.error;
return [{ json: { ok, account: 'instagram', token: $('Connect settings').first().json.token, ig_user_id: String(me.user_id || ''), username: me.username || '',
  expires_at: new Date(Date.now() + 60 * 864e5).toISOString(), refreshed_at: new Date().toISOString(),
  error: ok ? '' : String(igError(me.error) || 'No account came back').slice(0, 300) } }];

// One post per product, ever: a product with any row (draft, scheduled, posted, skipped, failed) is never picked again.
// Oldest products first. Skips accessories by word, small photos, products without a price or a description.
// Only the free slots in max_waiting are filled.
const s = $('Draft settings').first().json;
const posts = $('Get all posts').all().map(i => i.json).filter(r => r.product_id);
const pages = $('Get products').all().map(i => i.json);
const bad = pages.find(p => p.errors);
if (bad) throw new Error('Shopify: ' + JSON.stringify(bad.errors).slice(0, 300));
const products = pages.flatMap(p => p.data?.products?.nodes || []);
const free = Math.max(0, s.max_waiting - posts.filter(r => r.status === 'draft').length);
if (!free) return [];
const done = new Set(posts.map(r => String(r.product_id)));
const text = h => String(h || '').replace(/<li[^>]*>/gi, '; ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').replace(/^[;\s]+/, '').trim();
const skip = s.skip_words ? new RegExp(s.skip_words, 'i') : null;
const out = [];
for (const p of products) {
  const id = String(p.legacyResourceId);
  if (done.has(id) || (skip && skip.test(p.title))) continue;
  const img = p.featuredMedia?.image;
  if (!img || Math.min(img.width || 0, img.height || 0) < s.min_photo_px) continue;
  const amount = Number(p.priceRangeV2?.minVariantPrice?.amount);
  if (!(amount > 0) || text(p.descriptionHtml).length < 30) continue;
  const money = new Intl.NumberFormat(s.locale, { style: 'currency', currency: p.priceRangeV2.minVariantPrice.currencyCode,
    minimumFractionDigits: Number.isInteger(amount) ? 0 : 2, maximumFractionDigits: 2 }).format(amount);
  const desc = String(p.descriptionHtml || '');
  const cut = desc.search(/<h[2-4]/i);
  const url = p.onlineStoreUrl || (s.store_url.replace(/\/$/, '') + '/products/' + p.handle);
  const src = img.url.split('?')[0];
  out.push({ json: {
    product_id: id, product_title: p.title, handle: p.handle, brand: p.vendor || '', product_type: p.category?.name || p.productType || '',
    intro: text(cut >= 0 ? desc.slice(0, cut) : desc).slice(0, 800), specs: text(cut >= 0 ? desc.slice(cut) : '').slice(0, 3000),
    price: money, source_image: img.url, photo_url: src + '?width=1024',
    link: url + (url.includes('?') ? '&' : '?') + s.utm
  } });
  if (out.length >= free) break;
}
return out;

// The vision model's answer per photo, plus the input for the writer. A box shot or a diagram still gets a draft, flagged on the card.
const picked = $('Pick the next products').all().map(i => i.json);
const out = [];
$input.all().forEach((it, i) => {
  const p = picked[i]; if (!p) return;
  const r = it.json || {};
  let txt = r.content ?? r.text ?? r.response ?? r.message?.content ?? r.output ?? '';
  if (typeof txt !== 'string') txt = JSON.stringify(txt);
  let v = {};
  try { v = JSON.parse(txt.slice(txt.indexOf('{'), txt.lastIndexOf('}') + 1)); } catch (e) {}
  const kind = ['product', 'in_use', 'packaging', 'diagram', 'other'].includes(v.kind) ? v.kind : '';
  const alt = String(v.alt || '').replace(/\s+/g, ' ').trim().slice(0, 300);
  const lines = ['Product: ' + p.product_title, 'Brand: ' + (p.brand || 'unknown'), 'Product type: ' + (p.product_type || 'unknown'),
    'Intro: ' + (p.intro || 'none'), 'Specs: ' + (p.specs || 'none')];
  out.push({ json: { ...p, photo_kind: kind || null, photo_alt: alt, prompt_input: lines.join('\n') } });
});
return out;

// Parse the model's lines, build the caption in a fixed shape (hook, body, facts, the price line, hashtags) and hold it to the rules.
// Safe fixes are made here (dashes, casing, spelling, hashtag shape); anything else is a warning on the card. A model failure saves nothing.
const s = $('Draft settings').first().json;
const items = $('Read the photo').all().map(i => i.json);
const out = [];
$input.all().forEach((it, i) => {
  const p = items[i]; if (!p) return;
  const raw = String(it.json.text || it.json.output || '');
  if (it.json.error || !raw.trim()) return;   // tried again next run
  const grab = label => (raw.match(new RegExp('^\\s*\\**' + label + '\\**\\s*:\\s*(.+)$', 'gim')) || []).map(l => l.replace(/^[^:]*:\s*/, '').trim().replace(/^["“]|["”]$/g, ''));
  const fix = x => x.replace(/—|–/g, ', ').replace(/\s+,/g, ',').replace(/#\w+/g, '').replace(/\s{2,}/g, ' ').trim();
  const caps = x => s.keep_terms.reduce((t, k) => t.replace(new RegExp('\\b' + k.replace(/-/g, '-?') + '\\b', 'gi'), k), x);
  const local = x => /australian|british|new zealand|canadian/i.test(s.language)
    ? x.replace(/\bcolor(s|ed|ful)?\b/gi, (m, e) => (m[0] === 'C' ? 'Colour' : 'colour') + (e || '')).replace(/\bcenter(s|d)?\b/gi, (m, e) => (m[0] === 'C' ? 'Centre' : 'centre') + (e || '')).replace(/\b(meter|meters)\b/gi, m => m.replace(/er/i, 're'))
    : x;
  const clean = x => local(caps(fix(x || '')));
  const headline = clean(grab('Headline')[0]).replace(/\.{2,}/g, '.');
  const productLine = clean(grab('Product line')[0]).replace(/\s*[|•·]\s*|\s+-\s+/g, ' · ').replace(/(\s·\s)+/g, ' · ');
  const hook = clean(grab('Hook')[0]), body = clean(grab('Body')[0]);
  const facts = grab('Fact').map(f => clean(f).replace(/[.\s]+$/, '')).filter(Boolean).slice(0, 3);
  const tags = [...new Set(String(grab('Hashtags')[0] || '').split(/[\s,]+/).map(h => '#' + h.toLowerCase().replace(/[^a-z0-9]/g, '')).filter(h => h.length > 2))].slice(0, s.max_hashtags);
  const close = (p.price ? s.closing_line.replace('{price}', p.price) : s.closing_line_no_price).replace('{store}', s.store_name);
  const caption = [hook, body, facts.map(f => '• ' + f).join('\n'), close, tags.join(' ')].filter(Boolean).join('\n\n');
  const alt = (p.photo_alt ? p.photo_alt.replace(/\.?$/, '.') + ' ' : p.product_title + '. ') + 'Text on the image: ' + headline + ' ' + productLine;
  const problems = [];
  if (!headline) problems.push('No headline for the frame.');
  if (headline.length > 30) problems.push(`Headline is ${headline.length} characters (30 fits the frame).`);
  if (productLine.length > 58) problems.push(`Product line is ${productLine.length} characters; it will be cut off on the frame.`);
  if (caption.length > 2200) problems.push(`Caption is ${caption.length} characters (2,200 max).`);
  if (facts.length < 3) problems.push(`Only ${facts.length} facts.`);
  if (tags.length < 3) problems.push(`Only ${tags.length} hashtags.`);
  const all = [headline, productLine, hook, body, facts.join(' ')].join(' ');
  if (/https?:\/\/|www\./i.test(all)) problems.push('Has a web link.');
  if (/[$€£]\s?\d/.test(all)) problems.push('Mentions a price outside the closing line.');
  if (/\p{Extended_Pictographic}/u.test(all)) problems.push('Has an emoji.');
  const banned = s.banned_words ? all.replace(new RegExp(s.store_name, 'g'), '').match(new RegExp(s.banned_words, 'i')) : null;
  if (banned) problems.push(`Uses "${banned[0]}".`);
  if (/\b(this|the) (image|photo|picture|post)\b/i.test(all)) problems.push('Talks about the image instead of the product.');
  if (p.photo_kind && !['product', 'in_use'].includes(p.photo_kind)) problems.push(`The main photo looks like ${({ packaging: 'the box', diagram: 'a diagram or spec sheet' })[p.photo_kind] || 'something other than the product'}, not the product. Consider Skip, or change the main image in Shopify.`);
  out.push({ json: { ...p, headline, product_line: productLine, caption, alt_text: alt.slice(0, 1000), problems: JSON.stringify(problems) } });
});
return out;

// One Slack card for one post, in whatever state it is in. Every lane redraws the card through here, so it always matches the row.
const s = $('Card settings').first().json;
const r = $input.first().json;
const esc = x => String(x ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const when = t => t ? DateTime.fromISO(new Date(t).toISOString()).setZone(s.timezone).toFormat('ccc d LLL, h:mm a').replace('AM', 'am').replace('PM', 'pm') : '';
const head = { draft: 'Instagram draft', scheduled: 'Scheduled', publishing: 'Posting now', skipped: 'Skipped', posted: 'On Instagram', failed: 'Post failed' }[r.status] || 'Instagram';
const v = String(r.id);
const blocks = [{ type: 'header', text: { type: 'plain_text', text: (head + ': ' + r.product_title).slice(0, 150) } }];
if (r.status === 'skipped') {
  blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: 'Skipped by ' + esc(r.decided_by || 'someone') + '. This product won\'t get another Instagram post.' }, { type: 'mrkdwn', text: s.workflow_name }] });
  return [{ json: { channel: r.slack_channel, ts: r.slack_ts || '', id: r.id, text: 'Skipped: ' + r.product_title, blocks } }];
}
if (r.image_url) blocks.push({ type: 'image', image_url: r.image_url, alt_text: String(r.alt_text || r.product_title).slice(0, 1900) });
else blocks.push({ type: 'section', text: { type: 'mrkdwn', text: ':hourglass: The image is not ready yet.' + (r.error ? ' ' + esc(r.error) : ' Edit and save to draw it again.') } });
blocks.push({ type: 'section', fields: [
  { type: 'mrkdwn', text: '*Headline* (' + String(r.headline || '').length + ')\n' + esc(r.headline) },
  { type: 'mrkdwn', text: '*Product line* (' + String(r.product_line || '').length + ')\n' + esc(r.product_line) }] });
blocks.push({ type: 'section', text: { type: 'mrkdwn', text: ('*Caption* (' + String(r.caption || '').length + ')\n' + esc(r.caption)).slice(0, 2900) } });
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: 'Alt text: ' + esc(r.alt_text).slice(0, 600) }] });
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: 'Product page: <' + r.link + '|' + esc(String(r.link || '').split('?')[0].replace('https://', '')) + '>' }] });
let problems = []; try { problems = JSON.parse(r.problems || '[]'); } catch (e) {}
if (problems.length && r.status === 'draft') blocks.push({ type: 'section', text: { type: 'mrkdwn', text: ':warning: ' + problems.map(esc).join('\n:warning: ') } });
if (r.status === 'failed' && r.error) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: ':x: ' + esc(r.error).slice(0, 500) } });
const btn = (text, id, style) => Object.assign({ type: 'button', text: { type: 'plain_text', text }, action_id: id, value: v }, style ? { style } : {});
if (r.status === 'draft') blocks.push({ type: 'actions', elements: [btn('Approve', 'ig_approve', 'primary'), btn('Edit', 'ig_edit'), btn('Skip', 'ig_skip', 'danger')] });
if (r.status === 'scheduled') blocks.push({ type: 'actions', elements: [btn('Cancel', 'ig_cancel', 'danger')] });
if (r.status === 'failed') blocks.push({ type: 'actions', elements: [btn('Try again', 'ig_approve', 'primary'), btn('Edit', 'ig_edit'), btn('Skip', 'ig_skip', 'danger')] });
if (r.status === 'posted' && r.post_url) blocks.push({ type: 'actions', elements: [{ type: 'button', text: { type: 'plain_text', text: 'Open post' }, url: r.post_url, action_id: 'ig_open' }] });
const by = r.decided_by === 'auto' ? 'automatically' : 'by ' + esc(r.decided_by || 'someone');
const note = {
  draft: 'Approve books the next free slot. Edit changes the words (a new headline redraws the image). Skip means this product gets no post.',
  scheduled: ':calendar: Approved ' + by + '. Posts on ' + when(r.scheduled_for) + '. Cancel takes it back to a draft.',
  publishing: ':hourglass_flowing_sand: Posting to Instagram now.',
  posted: ':white_check_mark: On Instagram since ' + when(r.posted_at) + '.',
  failed: 'Not posted. Try again books a new slot.'
}[r.status] || '';
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: note }, { type: 'mrkdwn', text: s.workflow_name }] });
return [{ json: { channel: r.slack_channel, ts: r.slack_ts || '', id: r.id, text: head + ': ' + r.product_title, blocks } }];

// The frame as a 1080 x 1350 web page (4:5, the tallest Instagram feed shape): the real product photo in a panel,
// then the headline and the product line, then your name. Drawn from the saved row only.
const f = $('Frame settings').first().json;
const r = $input.first().json;
const esc = x => String(x ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
if (!r.id) return [{ json: { html: '<!doctype html><title>Not found</title><p>No post with that id.</p>', status: 404 } }];
const photo = String(r.source_image || '').split('?')[0] + '?width=1400';
const size = String(r.headline || '').length > 24 ? 72 : 84;
const brand = f.logo_url ? `<img src="${esc(f.logo_url)}" alt="${esc(f.store_name)}">` : `<span>${esc(f.store_name)}</span>`;
const html = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=1080">
<link href="https://fonts.googleapis.com/css2?family=${encodeURIComponent(f.font)}:wght@400;600;800&display=block" rel="stylesheet">
<style>*{box-sizing:border-box;margin:0}html,body{width:1080px;height:1350px;background:#fff}
body{font-family:'${f.font}',sans-serif;color:${f.text_colour};display:flex;flex-direction:column;padding:64px}
.photo{flex:0 0 820px;background:${f.panel_colour};border-radius:32px;display:flex;align-items:center;justify-content:center;overflow:hidden}
.photo img{max-width:86%;max-height:86%;object-fit:contain;mix-blend-mode:multiply}
.words{flex:1;display:flex;flex-direction:column;justify-content:center;padding:28px 8px 8px}
h1{font-size:${size}px;line-height:1.02;font-weight:800;letter-spacing:-0.02em}
.line{margin-top:18px;font-size:32px;color:${f.muted_colour};white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.foot{display:flex;justify-content:space-between;align-items:center;font-size:30px;font-weight:600}
.foot img{height:56px}.foot .dot{width:14px;height:14px;border-radius:50%;background:${f.accent_colour};display:inline-block;margin-right:14px}
.foot .url{color:${f.muted_colour};font-weight:400}
</style></head><body><div class="photo"><img src="${esc(photo)}" alt=""></div>
<div class="words"><h1>${esc(r.headline)}</h1><p class="line">${esc(r.product_line)}</p></div>
<div class="foot"><span><i class="dot"></i>${brand}</span><span class="url">${esc(f.store_url_text)}</span></div></body></html>`;
return [{ json: { html, status: 200 } }];

// The screenshot as a JPEG named after the product, by way of wsrv.nl (Instagram only takes JPEG). A failed screenshot is passed on with its error.
const s = $('Render settings').first().json;
const r = $('Get the post to draw').first().json;
const shot = $input.first().json?.data?.screenshot || '';
const name = ('instagram-' + String(r.product_title || 'post').toLowerCase().replace(/[^a-z0-9]+/g, '-').slice(0, 60) + '-' + r.id + '-' + Date.now()).replace(/-+/g, '-');
return [{ json: { id: r.id, old_file_id: r.shopify_file_id || '', alt: r.alt_text || '',
  source: shot ? s.jpeg_template.replace('{name}', name).replace('{url}', encodeURIComponent(shot)) : '',
  error: shot ? '' : 'Firecrawl: ' + String($input.first().json?.error?.message || $input.first().json?.error || 'no screenshot').slice(0, 200) } }];

// The image's lasting URL, or why there isn't one.
const n = $('Name the file').first().json;
const made = $('Keep it in Shopify').first().json;
const f = $input.first().json?.data?.node || {};
const id = made?.data?.fileCreate?.files?.[0]?.id || '';
// format=pjpg: Shopify's CDN sends WebP to anything that accepts it, and Instagram only takes JPEG.
const url = f.fileStatus === 'READY' && f.image?.url ? f.image.url + (f.image.url.includes('?') ? '&' : '?') + 'format=pjpg' : '';
const error = n.error || (!id ? 'Shopify: ' + JSON.stringify(made?.data?.fileCreate?.userErrors || made?.errors || 'no file').slice(0, 200) : (!url ? 'Shopify is still processing the image (' + (f.fileStatus || 'unknown') + '). Edit and save to draw it again.' : ''));
return [{ json: { id: n.id, file_id: id || n.old_file_id, image_url: url, error, old_file_id: url && n.old_file_id && n.old_file_id !== id ? n.old_file_id : '' } }];

// Slack sends the click as a form field called payload. Keep the raw body for the signature check.
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const h = $input.first().json.headers;
if (Math.abs(Date.now() / 1000 - Number(h['x-slack-request-timestamp'])) > 300) throw new Error('Stale request');
const field = raw.split('&').find(kv => kv.startsWith('payload=')) || '';   // no URLSearchParams in the Code node
const b = JSON.parse(decodeURIComponent(field.slice(8).replace(/\+/g, ' ')));
const sig = { base: `v0:${h['x-slack-request-timestamp']}:${raw}`, expected: h['x-slack-signature'] };
const user = b.user?.username || b.user?.name || b.user?.id || 'someone';
if (b.type === 'view_submission') {
  const m = JSON.parse(b.view.private_metadata || '{}');
  const v = b.view.state.values;
  const val = k => v[k]?.[k]?.value ?? null;
  return [{ json: { ...sig, action: 'edit_submit', post_id: String(m.post_id), user,
    edit: { headline: val('headline'), product_line: val('product_line'), caption: val('caption'), alt_text: val('alt_text') } } }];
}
const a = (b.actions || [])[0] || {};
return [{ json: { ...sig, action: String(a.action_id || '').replace('ig_', ''), post_id: String(a.value || ''), user,
  trigger_id: b.trigger_id, response_url: b.response_url || '' } }];

// The words of a draft in a modal. Saving a new headline or product line draws the image again.
const r = $('Get the clicked post').first().json;
const c = $('Read the click').first().json;
const input = (key, label, initial, max, multiline, optional) => ({ type: 'input', block_id: key, optional: !!optional, label: { type: 'plain_text', text: label },
  element: Object.assign({ type: 'plain_text_input', action_id: key, max_length: max, multiline: !!multiline }, initial ? { initial_value: String(initial).slice(0, max) } : {}) });
const editable = ['draft', 'failed'].includes(r.status);
const blocks = [{ type: 'section', text: { type: 'mrkdwn', text: '*' + String(r.product_title || 'Post').replace(/[<>&]/g, '') + '*' } }];
if (editable) blocks.push(input('headline', 'Headline on the image (30 fits)', r.headline, 60), input('product_line', 'Product line on the image (58 fits)', r.product_line, 90),
  input('caption', 'Caption', r.caption, 2200, true), input('alt_text', 'Alt text', r.alt_text, 1000, true, true));
else blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: 'This post is ' + r.status + '. Cancel it on the card first, then edit the draft.' }] });
const view = { type: 'modal', callback_id: 'ig_edit', private_metadata: JSON.stringify({ post_id: r.id }), title: { type: 'plain_text', text: 'Edit post' }, close: { type: 'plain_text', text: 'Close' }, blocks };
if (editable) view.submit = { type: 'plain_text', text: 'Save' };
return [{ json: { trigger_id: c.trigger_id, view } }];

// The edited words, held to the same rules as a new draft. Problems show on the card; nothing is blocked.
const r = $('Get the clicked post').first().json;
const e = $('Read the click').first().json.edit || {};
const one = (k, d) => (e[k] == null ? d : String(e[k]).replace(/\s+/g, ' ').trim());
const headline = one('headline', r.headline), product_line = one('product_line', r.product_line);
const caption = e.caption == null ? r.caption : String(e.caption).replace(/\r/g, '').replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
let alt_text = one('alt_text', r.alt_text);
if (headline !== r.headline || product_line !== r.product_line) alt_text = alt_text.replace(/Text on the image: .*$/, 'Text on the image: ' + headline + ' ' + product_line);
const problems = [];
if (headline.length > 30) problems.push(`Headline is ${headline.length} characters (30 fits the frame).`);
if (product_line.length > 58) problems.push(`Product line is ${product_line.length} characters; it will be cut off on the frame.`);
if (caption.length > 2200) problems.push(`Caption is ${caption.length} characters (2,200 max).`);
if ((caption.match(/#\w+/g) || []).length > 5) problems.push('More than 5 hashtags.');
if (/https?:\/\/|www\./i.test(caption)) problems.push('Has a web link (links in captions are not clickable).');
if (/\p{Extended_Pictographic}/u.test(headline + caption)) problems.push('Has an emoji.');
const redraw = headline !== r.headline || product_line !== r.product_line;
return [{ json: { headline, product_line, caption, alt_text, problems: JSON.stringify(problems), redraw, editable: ['draft', 'failed'].includes(r.status) } }];

// The next posting slot: one gap after the latest scheduled or posted post. The gap is a week divided by posts_per_week,
// jittered by up to 15% so posts don't land on the same minute, never sooner than 15 minutes from now, and moved into posting hours in your time zone.
const s = $('Book settings').first().json;
const post = $('Get the post to book').first().json;
const rows = $input.all().map(i => i.json).filter(r => r.id && String(r.id) !== String(post.id));
const ms = t => (t ? new Date(t).getTime() : NaN);
const now = Date.now(), gap = 7 * 864e5 / Math.max(Number(s.posts_per_week) || 1, 1);
const taken = rows.map(r => ms(r.status === 'posted' ? r.posted_at : r.scheduled_for)).filter(x => !isNaN(x));
const last = taken.length ? Math.max(...taken) : null;
let t = last == null ? now + 15 * 6e4 : Math.max(now + 15 * 6e4, last + gap + (Math.random() - 0.5) * 0.3 * gap);
if (s.first_slot_after) t = Math.max(t, ms(s.first_slot_after));
const [fh, fm] = s.post_from.split(':').map(Number), [uh, um] = s.post_until.split(':').map(Number);
let d = DateTime.fromMillis(t).setZone(s.timezone);
const mins = d.hour * 60 + d.minute;
if (mins < fh * 60 + fm || mins > uh * 60 + um) {
  if (mins > uh * 60 + um) d = d.plus({ days: 1 });
  d = d.set({ hour: fh, minute: fm, second: 0, millisecond: 0 }).plus({ minutes: Math.floor(Math.random() * 90) });
}
return [{ json: { id: post.id, slot: d.toUTC().toISO({ suppressMilliseconds: true }) } }];

// One post a run: the oldest scheduled post whose slot has passed. Nothing happens without a saved token.
const tok = $('Get the Instagram token').first().json;
const due = $input.all().map(i => i.json).filter(r => r.id && r.status === 'scheduled' && new Date(r.scheduled_for).getTime() <= Date.now())
  .sort((a, b) => new Date(a.scheduled_for) - new Date(b.scheduled_for));
if (!due.length || !tok.token || !tok.ig_user_id) return [];
return [{ json: { ...due[0], token: tok.token, ig_user_id: tok.ig_user_id } }];

// posted with the link, failed with Instagram's reason, or back to scheduled when the daily limit is used up.
// Instagram's own words from an HTTP error ('400 - "{\"error\":{\"message\": ...}}"'), else the raw message.
const igError = e => { const m = String(e?.message || e || ''); let t = m.slice(m.indexOf(' - ') + 3);
  for (let i = 0; i < 2; i++) { try { t = JSON.parse(t); } catch (x) { break; } if (typeof t !== 'string') break; }
  return (t && t.error && (t.error.error_user_msg || t.error.message)) || m; };
const r = $('Pick the due post').first().json;
const err = n => { if (!$(n).isExecuted) return ''; const j = $(n).last().json || {}; return j.error ? igError(j.error) : ''; };
const ran = n => $(n).isExecuted;
let out;
if (ran('Get the permalink')) {
  const p = $('Get the permalink').first().json;
  out = { status: 'posted', media_id: String($('Publish it').first().json.id), post_url: p.permalink || '', posted_at: p.timestamp ? new Date(p.timestamp).toISOString() : new Date().toISOString(), error: '' };
} else if (ran('Under the limit?') && !ran('Create the container')) {
  out = { status: 'scheduled', error: 'Instagram\'s daily API limit is used up. It goes out on a later run.' };
} else {
  const c = ran('Check the container') ? $('Check the container').last().json : {};
  const why = err('Publish it') || (c.status_code && c.status_code !== 'FINISHED' ? 'Instagram could not process the image (' + c.status_code + (c.status ? ': ' + c.status : '') + ').' : '')
    || err('Check the container') || err('Create the container') || err('Check the daily limit') || 'Unknown error';
  out = { status: 'failed', error: why.slice(0, 400) };
}
return [{ json: { id: r.id, container_id: ran('Create the container') ? String($('Create the container').first().json.id || '') : '', media_id: '', post_url: '', posted_at: null, ...out, product_title: r.product_title } }];

// The new token and its expiry, or the old one kept with a warning.
// Instagram's own words from an HTTP error ('400 - "{\"error\":{\"message\": ...}}"'), else the raw message.
const igError = e => { const m = String(e?.message || e || ''); let t = m.slice(m.indexOf(' - ') + 3);
  for (let i = 0; i < 2; i++) { try { t = JSON.parse(t); } catch (x) { break; } if (typeof t !== 'string') break; }
  return (t && t.error && (t.error.error_user_msg || t.error.message)) || m; };
const s = $('Token settings').first().json;
const row = $('Get the token to refresh').first().json || {};
const r = $input.first().json || {};
if (!row.token) return [{ json: { id: null, warn: ':warning: Instagram is not connected. Open the Save your Instagram token form.' } }];
const ok = !!r.access_token;
const expires = ok ? new Date(Date.now() + Number(r.expires_in || 5184000) * 1000).toISOString() : row.expires_at;
const days = Math.floor((new Date(expires).getTime() - Date.now()) / 864e5);
let warn = '';
if (!ok) warn = `:warning: Instagram token refresh failed (${String(igError(r.error) || 'no token came back').slice(0, 200)}). It runs out in ${days} days.`;
if (days < s.warn_days) warn = `:warning: The Instagram token runs out in ${days} days. ` + (ok ? '' : 'Paste a new one in the Save your Instagram token form.');
return [{ json: { id: row.id, token: ok ? r.access_token : row.token, expires_at: expires, refreshed_at: ok ? new Date().toISOString() : row.refreshed_at, warn } }];

// Last week's posts, the queue and when it runs out, and drafts that have waited too long.
const s = $('Report settings').first().json;
const rows = $input.all().map(i => i.json).filter(r => r.id);
const day = 864e5, now = Date.now();
const fmt = t => DateTime.fromISO(new Date(t).toISOString()).setZone(s.timezone).toFormat('ccc d LLL');
const posted = rows.filter(r => r.status === 'posted' && now - new Date(r.posted_at).getTime() < 7 * day);
const sched = rows.filter(r => r.status === 'scheduled').sort((a, b) => new Date(a.scheduled_for) - new Date(b.scheduled_for));
const drafts = rows.filter(r => r.status === 'draft');
const oldest = drafts.length ? Math.floor((now - Math.min(...drafts.map(r => new Date(r.createdAt).getTime()))) / day) : 0;
const failed = rows.filter(r => r.status === 'failed');
const lines = ['*Instagram this week*'];
lines.push(posted.length ? `Posted ${posted.length}: ` + posted.map(r => `<${r.post_url}|${r.product_title}>`).join(', ') : 'Nothing posted in the last 7 days.');
lines.push(sched.length ? `Scheduled: ${sched.length}. The queue runs out after ${fmt(sched[sched.length - 1].scheduled_for)}.` : ':warning: Nothing is scheduled, so nothing will post. Approve drafts in <#' + s.review_channel + '>.');
if (drafts.length) lines.push(`Waiting for review: ${drafts.length}, the oldest for ${oldest} day${oldest === 1 ? '' : 's'}.` + (oldest >= s.old_draft_days ? ' :warning:' : ''));
if (failed.length) lines.push(`Failed: ${failed.length} (Try again on each card).`);
return [{ json: { text: lines.join('\n') } }];
